<!-- This file is generated by AI. -->

<!--
  文件被外部修改时的裁决对话框: 磁盘上的内容与编辑器里这一份不同, 而编辑器里这一份**还没保存**。

  四条规则 (每条都对应一个踩过的坑):

  * **「保留编辑器内容」必须写盘**: 只"保留"而不写, 磁盘上仍是被外部改过的那一份, 下一次变更
    检查会再问一遍, 用户会陷入"每次都选保留、每次都再问"的死循环;
  * **裁决期间该文档暂停自动保存** (在 `editor/disk-sync.svelte.ts` 里判): 否则对话框还开着,
    800ms 后的自动保存就把内存那一份写了回去, 用户等于被自己的自动保存投了票;
  * **Esc / 点遮罩 = 暂不决定**: 同一份磁盘内容不再追问, 但冲突仍然挂着 (选项卡上有标记、自动
    保存继续暂停), 切走再切回来会重新询问;
  * **裁决之后配音历史要重新对齐**, 但这件事不在这里做 —— `disk-sync` 发出 `onExternalContent`
    通知, 配音卡自己订阅 (普通文档没有配音卡, 也就不需要)。

  对话框**不需要回调**: 裁决会删掉冲突记录、Esc 会把冲突标成"暂不决定", 父级的 `{#if}` 自然
  就把这个组件卸掉。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { dismissDiskConflict, resolveConflict, type ConflictChoice } from '../editor/disk-sync.svelte';
  import { openGitDiff } from '../git/diff';
  import { appStore } from '../state/store.svelte';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';

  let {
    path,
    /** 磁盘内容预览 (开头若干行, 可能为 null: 文件读不到时) */
    preview,
    /** 当前项目是否是 git 仓库 (不是就没有差异页可开) */
    inRepository,
  }: { path: string; preview: string | null; inRepository: boolean } = $props();

  let busy = $state(false);
  let error = $state<string | null>(null);

  async function run(choice: ConflictChoice): Promise<void> {
    busy = true;
    error = null;
    try {
      await resolveConflict(path, choice);
    } catch (e) {
      error = String(e);
    } finally {
      busy = false;
    }
  }

  /** 项目内相对路径 (差异选项卡要的是这个, 不是绝对路径)。 */
  function relativeToProject(): string {
    const projectPath = appStore.projectPath;
    if (!projectPath) return path;
    const base = projectPath.replace(/\\/g, '/').replace(/\/+$/, '');
    const full = path.replace(/\\/g, '/');
    return full.toLowerCase().startsWith(`${base.toLowerCase()}/`) ? full.slice(base.length + 1) : full;
  }

  /**
   * 打开只读的 git 差异页 (工作区 vs 索引)。
   *
   * 不碰冲突状态: 去看差异不等于做了裁决。差异卡没有对应文档, 切过去之后这个对话框自然消失
   * (活动文档为空), 切回来再问一次。
   */
  function openDiff(): void {
    if (!inRepository) return;
    openGitDiff(relativeToProject(), 'unstaged');
  }
</script>

<AppDialog
  title="文件已被外部修改"
  iconName="Warning"
  description={path}
  size="medium"
  closeOnBackdrop
  onClose={() => dismissDiskConflict(path)}
>
  <p class="voice-dialog-hint">
    这份文件在磁盘上被改过（例如切换分支、还原历史、外部编辑器或另一个窗口），而编辑器里这一份还没保存。
    在做选择之前，这个文件不会自动保存 —— 免得把磁盘上的新内容又盖回去。
    「保留编辑器内容」会把编辑器里的这一份写回磁盘（此后以它为准, 不会再反复询问）；「加载磁盘内容」改用磁盘上的那一份；
    「备份后加载磁盘」先把手上这一份另存到同目录, 再加载磁盘。「查看差异」打开只读的 git 差异页。 按 Esc 表示暂不决定,
    切回这个文件时会再问一次。
  </p>

  <!-- 磁盘上那一份的开头几行: 让用户不必先"加载"就能判断该留哪一份 -->
  {#if preview}
    <pre class="disk-conflict-preview" aria-label="磁盘上的内容（开头若干行）">{preview}</pre>
  {/if}

  {#if error}
    <p class="voice-error">{error}</p>
  {/if}

  {#snippet footerLeading()}
    <Button disabled={busy} title="先把编辑器里的内容另存一份, 再加载磁盘" onclick={() => void run('backup-take-disk')}>
      备份后加载磁盘
    </Button>
  {/snippet}

  {#snippet footer()}
    <Button
      disabled={busy}
      title="用编辑器里的内容覆盖磁盘文件（此后以这一份为准）"
      onclick={() => void run('keep-editor')}
    >
      保留编辑器内容（覆盖磁盘）
    </Button>
    <Button
      disabled={busy || !inRepository}
      title={inRepository ? '打开只读差异页, 逐块查看磁盘与 git 索引的差别' : '当前项目不在 git 仓库中'}
      onclick={openDiff}
    >
      查看差异
    </Button>
    <Button appearance="primary" disabled={busy} onclick={() => void run('take-disk')}>加载磁盘内容</Button>
  {/snippet}
</AppDialog>
